import sys
import itertools

def main():
    m = sys.stdin.read().strip()
    n = len(m)

    segments = []
    current_length = 0

    for char in m:
        if char == '#':
            if current_length == 0:
                segments.append(0)
            current_length += 1
        else:
            if current_length > 0:
                segments[-1] = current_length
                current_length = 0
            segments.append(0)

    if current_length > 0:
        segments[-1] = current_length

    if segments[0] == 0:
        segments.pop(0)
    if segments and segments[-1] == 0:
        segments.pop()

    if not segments:
        print("0")
        return

    gaps = [segments[i] for i in range(1, len(segments), 2)]
    if any(gap == 0 for gap in gaps):
        print("-1")
        return

    profile = [segments[i] for i in range(0, len(segments), 2)]
    print(len(profile))
    print(' '.join(map(str, profile)))

